-- Title-level book state preserves separate production and publication evidence.
-- Cover approval never proves manuscript completion or publication.
alter table public.command_center_book_catalogue
 add column if not exists project_id text,
 add column if not exists production_state text,
 add column if not exists production_percent numeric check(production_percent between 0 and 100),
 add column if not exists publication jsonb not null default '{}'::jsonb,
 add column if not exists state_evidence_refs text[] not null default '{}'::text[],
 add column if not exists state_observed_at timestamptz;
alter table public.command_center_book_catalogue drop constraint command_center_book_catalogue_catalogue_order_check;
alter table public.command_center_book_catalogue add constraint command_center_book_catalogue_catalogue_order_check check(catalogue_order>=1);
alter table public.command_center_book_catalogue alter column cover_slot drop not null,alter column cover_asset_ref drop not null,alter column cover_blob_sha drop not null;
-- Approved covers remain protected; absent art is never misrepresented as approved.
alter table public.command_center_book_catalogue add constraint book_catalogue_approved_cover_requires_asset check(not cover_approved or (cover_slot is not null and cover_slot between 0 and 40 and cover_asset_ref is not null and cover_blob_sha is not null));
insert into public.command_center_book_catalogue(owner_id,book_id,catalogue_order,title,author_name,cover_approved,source_ref)
select distinct owner_id,'book:catalogue:042',42,'The Weight Between Tasks','James Morgan',false,'library:libfile_9ddd9ccb50ec81918fb45da013a0fc54' from public.command_center_book_catalogue on conflict(owner_id,book_id) do nothing;
insert into public.command_center_book_catalogue(owner_id,book_id,catalogue_order,title,author_name,cover_approved,source_ref)
select distinct owner_id,'book:catalogue:043',43,'The Last Hour I Trusted You','James Morgan',false,'supabase:cc7_projects:kdp-standalones' from public.command_center_book_catalogue on conflict(owner_id,book_id) do nothing;
